import React from 'react'
import { Link } from 'react-router-dom'
import DefaultImg from '../assets/default-img.jpg'

const Categ = ({ categ, handleDeleteClick, user }) => (
  <div>
    <h4>{categ.name}</h4>
    <Link to={`/categ/${categ.id}`}>
      <img src={categ.image !== undefined ? `${categ.image.imageData}` : `${DefaultImg}`} alt="image" className="process__image" />
    </Link>
    <form>
      {user !== undefined && categ.user !== undefined && user.username === categ.user.username &&
      <button class="btn btn-danger" onClick={() =>
        handleDeleteClick(categ)}>
        Delete
      </button>
      }
    </form>
  </div>
)

export default Categ